<template>
  <div class="inquiry-scroll">
  <LessonWorkspace v-if="lessonMode" :initial-workspace="lessonWorkspace" :sources="sources" @close="closeLesson" />
  <main v-else class="studio">
    <header><strong>✳ Inquiry Studio</strong><div><button @click="showHistory = !showHistory">历史记录</button><button @click="leave">返回对话模式</button></div></header>
    <div v-if="error" class="alert" role="alert">{{ error }} <button @click="error = ''" aria-label="关闭错误">×</button></div>
    <section v-if="showHistory" class="history" aria-label="历史工作空间"><h2>历史工作空间</h2><p v-if="!history.length">还没有保存的工作空间。</p><button v-for="item in history" :key="item.id" @click="openWorkspace(item.id)">{{ item.title }} →</button></section>
    <section v-if="!workspace && !designMode" class="home">
      <span class="eyebrow">INQUIRY STUDIO</span><h1>让每一节课，都更值得探索</h1><p>从教学设计到教案优化，让专业教学知识支持你的课堂。</p>
      <div class="entry-grid"><div><strong>教学设计</strong><p>从教学想法开始，生成探究式教学方案。</p><button @click="designMode = true">进入教学设计</button></div><div><strong>教案分析</strong><p>导入教案，编辑并保存版本，通过教学助手获取通用建议。</p><button @click="lessonWorkspace = null; lessonMode = true">导入教案 →</button></div></div>
    </section>
    <section v-else-if="!workspace" class="home design-home">
      <button class="link back-home" @click="designMode = false">← 返回首页</button>
      <span class="eyebrow">LESSON DESIGN</span><h1>今天想设计一节什么课？</h1><p>描述你的教学需求，按需选择课程场景。</p>
      <div class="composer"><textarea v-model="goal" aria-label="教学需求" placeholder="例如：设计一节小学四年级校园垃圾分类探究课，40 分钟。"></textarea><div class="recognition" aria-label="需求识别">{{ recognition }}</div>
        <div class="scene-row"><strong>课程场景</strong><span v-for="id in selected" :key="id" class="tag">{{ scenes.find(s => s.id === id)?.name }} <button :aria-label="`移除${id}`" @click="toggleScene(id)">×</button></span><button class="link" @click="selector = true">{{ selected.length ? '调整场景' : '+ 选择场景' }}</button><button v-if="recommendation && !selected.includes(recommendation.id)" class="link" @click="toggleScene(recommendation.id)">推荐：{{ recommendation.name }} ＋</button></div>
        <p class="consent">暂无可用知识依据时，将使用通用教学建议继续，并标注依据缺失。</p>
        <div class="composer-actions"><small>场景为可选；实际来源由服务端授权。</small><button class="primary" :disabled="busy || !goal.trim()" @click="start">开始设计 ↗</button></div>
      </div>
      <p class="examples">从一个想法开始</p><div class="chips"><button v-for="example in examples" :key="example.label" @click="goal = example.text">{{ example.label }}</button></div>
    </section>
    <section v-else class="workspace">
      <div class="workspace-head"><div><button class="link" @click="newWorkspace">← 创建新任务</button><h1>{{ workspace.title }}</h1></div><div><span class="state" role="status">{{ running ? '正在生成' : editingId ? '有未保存的修改' : '已保存到服务器' }}</span><button :disabled="running || !!editingId" @click="exportDocument">下载 Word</button></div></div>
      <div v-if="run" class="progress" role="status"><strong>{{ statusLabel }}</strong><span v-if="run.error"> · {{ run.error }}</span><p v-for="warning in uniqueWarnings" :key="warning">{{ warning }}</p><button v-if="running" @click="cancel">取消生成</button><button v-if="disconnected && running" @click="reconnect">重新连接</button></div>
      <details v-if="admin && run" @toggle="loadDiagnostics"><summary>查看设计过程（管理员）</summary><p v-if="!diagnostics">加载执行信息…</p><div v-else><p>知识状态：{{ diagnostics.context_status || '尚未记录' }} · 检索意图：{{ diagnostics.retrieval_intents.join('、') || '尚未记录' }}</p><p v-for="node in diagnostics.nodes" :key="node.id">{{ node.capability }} · {{ node.status }} · {{ node.input_summary }} · {{ node.output_summary }} <span v-if="node.error_message"> · {{ node.error_message }}</span></p><p v-for="ref in diagnostics.evidence_refs" :key="ref.evidence_id">{{ ref.title }} · {{ ref.evidence_id }} · {{ ref.source_version }}</p></div></details>
      <nav class="tabs" aria-label="教学成果"><button v-for="item in tabs" :key="item.id" :class="{active: tab === item.id}" @click="changeTab(item.id)">{{ item.label }}</button></nav>
      <article class="document"><h2>{{ tabs.find(t => t.id === tab)?.label }}</h2><p v-if="!visibleArtifacts.length" class="muted">{{ running ? '正在等待后端生成成果。' : '暂无成果；失败或取消的任务不会显示模拟内容。' }}</p>
        <section v-for="artifact in visibleArtifacts" :key="artifact.id" class="artifact"><div class="artifact-heading"><h3>{{ artifact.content.title || artifact.type }}</h3><div><button class="link" :disabled="running || !!editingId" @click="showVersions(artifact)">历史版本</button><button class="link" :disabled="running || artifact.locked || (!!editingId && editingId !== artifact.id)" @click="beginEdit(artifact)">编辑</button></div></div>
          <p v-if="artifact.status === 'stale' || artifact.review_status === 'needs_review'" class="alert">关联内容已变化，请检查本成果。 <button :disabled="running || !!editingId" @click="confirmReview(artifact)">已检查</button></p>
          <div v-if="versionsFor === artifact.id" class="version-list"><strong>历史版本</strong><button class="link" @click="versionsFor = ''">关闭</button><div v-for="version in versions" :key="version.version"><span>版本 {{ version.version }} · {{ version.created_at }}</span> <button v-if="version.version !== artifact.version" :disabled="running" @click="restoreVersion(artifact, version.version)">恢复</button><details><summary>查看内容</summary><pre>{{ JSON.stringify(version.content, null, 2) }}</pre></details></div></div>
          <template v-if="editingId === artifact.id"><label>修改字段 <select :value="editingField" @change="chooseField(artifact, $event)"><option v-for="key in editableFields(artifact)" :key="key" :value="key">{{ fieldLabels[key] }}</option></select></label><label>修改内容<textarea v-model="draft" rows="5"></textarea></label><div class="edit-actions"><button @click="editingId = ''">取消</button><button class="primary" :disabled="busy" @click="saveEdit(artifact)">保存</button></div></template>
          <template v-else><p v-for="line in displayLines(artifact)" :key="line" class="content-line">{{ line }}</p></template>
          <details><summary>查看设计依据</summary><p v-if="!artifact.source_refs.length">暂无已核实的知识依据；请教师确认。</p><ul v-else><li v-for="(source, i) in artifact.source_refs" :key="i">{{ source.title || source.source }} · 版本 {{ source.source_version || '待核实' }}<p v-if="source.snippet">{{ source.snippet }}</p></li></ul></details>
          <small>版本 {{ artifact.version }}</small>
        </section>
      </article><p class="muted">自然语言局部智能修改暂不可用；可直接编辑并保存成果。</p>
    </section>
    <SceneSelector v-if="selector" :scenes="scenes" :sources="sources" :selected="selected" :selected-sources="selectedSources" @close="selector = false" @toggle="toggleScene" @toggle-source="toggleSource" />
  </main>
  </div>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import SceneSelector from './SceneSelector.vue';
import LessonWorkspace from './LessonWorkspace.vue';
import { request, json, eventsUrl, downloadSnapshot, type Artifact, type Run, type Scene, type Source, type Workspace } from './api';
const emit = defineEmits<{close: []}>();
defineProps<{admin: boolean}>();
const diagnostics = ref<{context_status: string | null; retrieval_intents: string[]; nodes: Array<{id:string; capability:string; status:string; input_summary:string; output_summary:string; error_message?:string}>; evidence_refs: Array<{evidence_id:string; title:string; source_version:string}>} | null>(null);
const goal = ref(''), error = ref(''), busy = ref(false), selector = ref(false), showHistory = ref(false), disconnected = ref(false);
const scenes = ref<Scene[]>([]), sources = ref<Source[]>([]), selected = ref<string[]>([]), selectedSources = ref<string[]>([]);
const workspace = ref<Workspace | null>(null), run = ref<Run | null>(null), history = ref<Array<{id: string; title: string}>>([]);
const lessonMode = ref(false), lessonWorkspace = ref<Workspace | null>(null), designMode = ref(false);
const editingId = ref(''), editingField = ref(''), draft = ref(''), editBaseline = ref(''), tab = ref('plan');
const versionsFor = ref(''), versions = ref<Array<{version: number; created_at: string; content: Record<string, unknown>}>>([]);
let stream: EventSource | null = null, cursor = 0;
const tabs = [{id: 'plan', label: '教学方案'}, {id: 'sheet', label: '学生任务单'}, {id: 'assessment', label: '学习评价'}];
const examples = [{label:'科学 · 种子发芽',text:'设计一节小学三年级科学《种子发芽》探究课，40分钟。'}, {label:'语文 · 校园故事',text:'设计一节小学四年级语文《校园里的故事》探究课，40分钟。'}, {label:'数学 · 校园用水',text:'设计一节小学四年级数学《校园用水数据调查》探究课，40分钟。'}, {label:'跨学科 · 垃圾分类',text:'设计一节小学四年级跨学科《校园垃圾分类》探究课，40分钟。'}];
const recognition = computed(() => { const q = goal.value; return `学科：${q.match(/跨学科|科学|语文|数学/)?.[0] || '待确认'} · 年级：${q.match(/[一二三四五六1-6]年级/)?.[0] || '待确认'} · 课时：${q.match(/\d+\s*分钟/)?.[0] || '待确认'} · 主题：${q.match(/《([^》]+)》/)?.[1] || '待确认'}`; });
const recommendation = computed(() => { const text = goal.value; const id = /用水|数据|统计/.test(text) ? 'data_survey' : /种子|发芽|实验/.test(text) ? 'science_lab' : /校园|垃圾/.test(text) ? 'campus_life' : ''; return scenes.value.find(s => s.id === id); });
const running = computed(() => !!run.value && ['queued','planning','running','evaluating'].includes(run.value.status));
const uniqueWarnings = computed(() => [...new Set(run.value?.warnings || [])]);
const visibleArtifacts = computed(() => (workspace.value?.artifacts || []).filter(a => tab.value === 'sheet' ? a.type === 'StudentWorksheet' : tab.value === 'assessment' ? a.type === 'Assessment' : !['StudentWorksheet','Assessment'].includes(a.type)));
const statusLabel = computed(() => { if (!run.value) return ''; const current = run.value.nodes.find(n => n.status === 'running'); if (current) return ({'context.enrich@1':'正在查找教学依据','lesson.bundle@1':'正在设计探究活动','quality.rules@1':'正在检查成果'} as Record<string,string>)[current.capability] || '正在处理'; return ({queued:'等待执行',planning:'正在理解教学需求',running:'正在整理教学资源',completed:'教学资源已生成',failed:'生成失败',cancelled:'已取消',waiting_review:'需要教师审核'} as Record<string,string>)[run.value.status] || run.value.status; });
function toggleScene(id: string) { selected.value = selected.value.includes(id) ? selected.value.filter(s => s !== id) : selected.value.length < 3 ? [...selected.value, id] : selected.value; if (!selected.value.includes('custom')) selectedSources.value = []; }
function toggleSource(id: string) { selectedSources.value = selectedSources.value.includes(id) ? selectedSources.value.filter(s => s !== id) : [...selectedSources.value, id]; }
async function loadHistory() { history.value = await request('/api/inquiry-workspaces'); }
async function refresh() { if (!workspace.value) return; workspace.value = await request<Workspace>(`/api/inquiry-workspaces/${workspace.value.id}`); run.value = workspace.value.latest_run; }
async function loadDiagnostics(event: Event) { if (!(event.target as HTMLDetailsElement).open || !workspace.value || !run.value) return; diagnostics.value = null; try { diagnostics.value = await request(`/api/inquiry-workspaces/${workspace.value.id}/runs/${run.value.id}/diagnostics`); } catch (e) { error.value = e instanceof Error ? e.message : '无法读取执行信息'; } }
async function start() { if (!goal.value.trim()) return; busy.value = true; error.value = ''; try { const created = await request<{id:string;title:string}>('/api/inquiry-workspaces', json('POST', {title: goal.value.trim()})); workspace.value = { ...created, artifacts: [], latest_run: null }; run.value = await request<Run>(`/api/inquiry-workspaces/${created.id}/runs`, json('POST', {goal:goal.value.trim(), mode:'lesson', studio_mode:true, scene_ids:selected.value, custom_source_ids:selectedSources.value, idempotency_key:crypto.randomUUID()})); cursor = 0; connect(); await loadHistory(); } catch (e) { error.value = e instanceof Error ? e.message : '创建失败'; } finally { busy.value = false; } }
function connect() { if (!workspace.value || !run.value) return; stream?.close(); disconnected.value = false; const ws = workspace.value.id, id = run.value.id; stream = new EventSource(eventsUrl(ws, id, cursor), {withCredentials: true}); for (const kind of ['queued','planning','running','node_started','node_succeeded','node_failed','completed','failed','cancelled','waiting_review','access_revoked']) stream.addEventListener(kind, async (event: Event) => { const message = event as MessageEvent; if (message.lastEventId) cursor = Number(message.lastEventId); if (kind === 'access_revoked') { stream?.close(); error.value = '访问权限已失效'; return; } try { run.value = await request<Run>(`/api/inquiry-workspaces/${ws}/runs/${id}`); if (!running.value) { stream?.close(); await refresh(); } } catch (e) { stream?.close(); error.value = e instanceof Error ? e.message : '无法读取运行状态'; } }); stream.onerror = () => { if (running.value) disconnected.value = true; }; }
function reconnect() { connect(); }
async function cancel() { if (!workspace.value || !run.value) return; try { run.value = await request<Run>(`/api/inquiry-workspaces/${workspace.value.id}/runs/${run.value.id}/cancel`, {method:'POST'}); stream?.close(); await refresh(); } catch (e) { error.value = e instanceof Error ? e.message : '取消失败'; } }
const fieldLabels: Record<string,string> = {paragraphs:'正文',teacher_preparation:'教师准备',description:'教师引导',question:'探究问题',student_instructions:'学生任务',evidence:'学习证据',materials:'材料',safety_measures:'安全提醒',steps:'步骤',criteria:'评价指标'};
function editableFields(a: Artifact): string[] { return Object.keys(fieldLabels).filter(key => typeof a.content[key] === 'string' || Array.isArray(a.content[key])); }
function displayLines(a: Artifact): string[] { const labels: Record<string,string> = {paragraphs:'',teacher_preparation:'教师准备',description:a.type === 'InquiryActivity' ? '教师引导' : '',question:'问题',student_instructions:'学生任务',minutes:'活动时间（分钟）',evidence:'学习证据',materials:'材料',safety_measures:'安全提醒',steps:'步骤',criteria:'评价指标'}; return Object.entries(a.content).filter(([key]) => key in labels).map(([key, value]) => `${labels[key] ? labels[key] + '：' : ''}${Array.isArray(value) ? value.join('\n') : String(value ?? '')}`); }
function changeField(a: Artifact, key: string) { editingField.value = key; const value = a.content[key]; draft.value = Array.isArray(value) ? value.join('\n') : String(value ?? ''); editBaseline.value = draft.value; }
function chooseField(a: Artifact, event: Event) { const select = event.target as HTMLSelectElement; if (draft.value !== editBaseline.value && !window.confirm('当前字段尚未保存，确定切换吗？')) { select.value = editingField.value; return; } changeField(a, select.value); }
function beginEdit(a: Artifact) { const fields = editableFields(a); if (!fields.length) { error.value = '当前成果没有可编辑的文本字段。'; return; } editingId.value = a.id; changeField(a, fields[0]!); }
async function saveEdit(a: Artifact) { if (!workspace.value) return; busy.value = true; try { const key = editingField.value, value = Array.isArray(a.content[key]) ? draft.value.split('\n').filter(Boolean) : draft.value; await request(`/api/inquiry-workspaces/${workspace.value.id}/artifacts/${a.id}`, json('PATCH', {expected_version:a.version, content:{...a.content, [key]:value}})); editingId.value = ''; await refresh(); } catch (e) { error.value = e instanceof Error ? e.message : '保存失败'; } finally { busy.value = false; } }
async function confirmReview(a: Artifact) { if (!workspace.value) return; try { await request(`/api/inquiry-workspaces/${workspace.value.id}/artifacts/${a.id}/review`, json('POST', {expected_version:a.version})); await refresh(); } catch (e) { error.value = e instanceof Error ? e.message : '确认失败'; } }
async function showVersions(a: Artifact) { if (!workspace.value) return; try { versions.value = await request(`/api/inquiry-workspaces/${workspace.value.id}/artifacts/${a.id}/versions`); versionsFor.value = a.id; } catch (e) { error.value = e instanceof Error ? e.message : '版本读取失败'; } }
async function restoreVersion(a: Artifact, version: number) { if (!workspace.value || !window.confirm('恢复会创建新版本，确定继续吗？')) return; try { await request(`/api/inquiry-workspaces/${workspace.value.id}/artifacts/${a.id}/restore`, json('POST', {expected_version:a.version, version})); versionsFor.value = ''; await refresh(); } catch (e) { error.value = e instanceof Error ? e.message : '恢复失败'; } }
function confirmLeave() { return !editingId.value || window.confirm('当前编辑尚未保存，确定离开吗？'); }
function changeTab(id: string) { if (confirmLeave()) { editingId.value = ''; tab.value = id; } }
function leave() { if (confirmLeave() && (!running.value || window.confirm('任务仍在运行，确定返回对话模式吗？'))) emit('close'); }
function newWorkspace() { if (!confirmLeave() || (running.value && !window.confirm('任务仍在运行，确定离开吗？'))) return; stream?.close(); workspace.value = null; run.value = null; designMode.value = true; editingId.value = ''; error.value = ''; }
async function openWorkspace(id: string) { if (!confirmLeave()) return; try { const opened = await request<Workspace>(`/api/inquiry-workspaces/${id}`); stream?.close(); if (opened.artifacts.some(a => a.type === 'LessonDocument')) { lessonWorkspace.value = opened; lessonMode.value = true; showHistory.value = false; return; } workspace.value = opened; run.value = opened.latest_run; editingId.value = ''; showHistory.value = false; cursor = 0; if (running.value) connect(); } catch (e) { error.value = e instanceof Error ? e.message : '打开失败'; } }
async function closeLesson() { lessonMode.value = false; lessonWorkspace.value = null; workspace.value = null; run.value = null; designMode.value = false; try { await loadHistory(); } catch (e) { error.value = e instanceof Error ? e.message : '历史加载失败'; } }
async function exportDocument() { if (!workspace.value) return; try { const snapshot = await request<{id:string}>(`/api/inquiry-workspaces/${workspace.value.id}/report/snapshots`, {method:'POST'}); await downloadSnapshot(workspace.value.id, snapshot.id); } catch (e) { error.value = e instanceof Error ? e.message : '下载失败'; } }
function beforeUnload(event: BeforeUnloadEvent) { if (editingId.value && draft.value !== editBaseline.value) { event.preventDefault(); event.returnValue = ''; } }
onMounted(async () => { window.addEventListener('beforeunload', beforeUnload); try { [scenes.value, sources.value] = await Promise.all([request<Scene[]>('/api/inquiry-scenes'), request<Source[]>('/api/inquiry-scenes/sources')]); await loadHistory(); } catch (e) { error.value = e instanceof Error ? e.message : '加载失败'; } });
onBeforeUnmount(() => { stream?.close(); window.removeEventListener('beforeunload', beforeUnload); });
</script>
<style scoped>
.inquiry-scroll{height:100%;min-height:0;overflow-x:hidden;overflow-y:auto}
.studio{min-height:100vh;background:#f5f8f6;color:#183a33;font:15px/1.7 system-ui,sans-serif}.studio *{box-sizing:border-box}.studio button,.studio textarea{font:inherit}.studio button{cursor:pointer;border:1px solid #d5e4dc;background:white;color:#183a33;border-radius:9px;padding:8px 13px}.studio button:focus-visible,.studio textarea:focus-visible{outline:3px solid #9dd3bf}.studio button:disabled{opacity:.5;cursor:not-allowed}.studio header{height:70px;background:white;border-bottom:1px solid #d5e4dc;display:flex;justify-content:space-between;align-items:center;padding:0 max(20px,calc((100vw - 1080px)/2));gap:10px}.studio header div{display:flex;gap:8px}.home{max-width:760px;margin:10vh auto;padding:0 20px;text-align:center}.home h1{font-size:clamp(28px,4vw,40px);margin:10px 0}.home p,.muted,.state{color:#70877c}.eyebrow{color:#27816c;font-size:12px;letter-spacing:.14em}.composer{background:#fff;border:1px solid #d5e4dc;border-radius:16px;padding:18px;text-align:left;margin-top:28px}.composer textarea{border:0;resize:vertical;width:100%;min-height:120px}.scene-row{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:13px;margin:10px 0}.studio .link{border:0;padding:2px;background:transparent;color:#27816c}.tag{background:#edf7f1;border-radius:20px;padding:3px 9px}.tag button{border:0;padding:0;background:transparent}.consent{display:block;color:#526f62;font-size:13px;padding:8px 0}.composer-actions{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #edf2ef;padding-top:12px;gap:10px}.studio .primary{background:#27816c;color:#fff;border-color:#27816c}.chips{display:flex;justify-content:center;gap:8px;flex-wrap:wrap}.chips button{border-radius:30px}.workspace,.history{max-width:1080px;margin:auto;padding:28px 20px}.workspace-head{display:flex;justify-content:space-between;gap:15px}.workspace-head h1{margin:6px 0;font-size:27px}.workspace-head>div:last-child{display:flex;align-items:center;gap:10px}.tabs{display:flex;gap:15px;border-bottom:1px solid #d5e4dc;overflow:auto}.tabs button{border:0;border-radius:0;background:transparent;white-space:nowrap}.tabs .active{color:#27816c;border-bottom:2px solid #27816c}.document{background:white;border:1px solid #d5e4dc;border-radius:0 0 16px 16px;padding:30px clamp(20px,7vw,80px)}.artifact{border-bottom:1px solid #edf2ef;padding:18px 0}.artifact-heading{display:flex;justify-content:space-between}.artifact h3{margin:0}.content-line{white-space:pre-wrap;color:#476459}.artifact textarea{display:block;width:100%;padding:8px;border:1px solid #d5e4dc;border-radius:8px}.edit-actions{display:flex;justify-content:flex-end;gap:8px;margin:8px 0}.artifact details{font-size:13px;color:#27816c}.artifact small{color:#70877c}.version-list{padding:10px;background:#f5f8f6;overflow-wrap:anywhere}.version-list pre{white-space:pre-wrap;overflow-wrap:anywhere}.progress,.alert{background:#edf7f1;border:1px solid #d5e4dc;border-radius:10px;padding:12px;margin:15px 0}.alert{max-width:1040px;margin:15px auto;color:#933d31}.history button{display:block;width:100%;text-align:left;margin:6px 0}@media(max-width:650px){.studio header{height:auto;padding:12px;flex-wrap:wrap}.workspace-head{display:block}.workspace-head>div:last-child{margin:12px 0;flex-wrap:wrap}.composer-actions{flex-wrap:wrap}.document{padding:24px 18px}}
.home{max-width:1600px;width:calc(100% - 40px);margin:6vh auto}.entry-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;text-align:left;margin:26px 0}.entry-grid>div{background:white;border:1px solid #d5e4dc;border-radius:14px;padding:24px}.entry-grid strong{font-size:20px}.entry-grid p{margin:8px 0 16px}.composer{max-width:100%;margin:20px auto}.studio header{padding:0 clamp(20px,3vw,48px)}@media(max-width:650px){.entry-grid{grid-template-columns:1fr}.studio header{height:auto;padding:12px}}
.design-home{max-width:1080px}.design-home .back-home{display:block;margin-bottom:20px}
